-- =============================================================================
-- 0007 — Missions 1-2 "Power Station" and 1-3 "Supply Run" (mission framework)
--
-- Apply after 0004 (independent of 0005):
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f database/migrations/0007_power_station_supply_run.sql
-- (or paste into the Neon SQL Editor). One transaction; safe to run again.
--
-- Rebuilds starter-02 as "Power Station" (waypoints, left and right turns,
-- stop on the charging pad) and starter-03 as "Supply Run" (plan a route
-- around storm debris, cross the creek bridge, stop on the clinic pad), each
-- with briefing, scoring, stop-in-finish and four tiered hints, and renames
-- their environments. Progress, stars and XP are kept; objective ticks of
-- these levels are reset because their objectives changed.
-- =============================================================================
BEGIN;

UPDATE environments SET name = 'Power Station', description = 'The island power yard: hedge-lined service lanes, transformers, pylons and the charging pad.' WHERE id = 'starter-campus-crossing';
UPDATE environments SET name = 'Supply Trail', description = 'A storm-hit meadow trail over the creek bridge to the riverside clinic.' WHERE id = 'starter-creek-bridge';

-- starter-02 · Power Station
UPDATE levels SET title = 'Power Station', brief_description = 'The power yard is dark. Inspect both transformers on the service lanes and park on the charging pad so the station can reboot.',
       description = 'The power yard is dark. Inspect both transformers on the service lanes and park on the charging pad so the station can reboot. Environment: Power Station — The island power yard: hedge-lined service lanes, transformers, pylons and the charging pad.',
       difficulty = 'BEGINNER', environment_id = 'starter-campus-crossing', estimated_minutes = 6,
       xp_reward = 75, par_blocks = 8, par_seconds = 26,
       allowed_blocks = ARRAY['event.start', 'motion.forward', 'motion.backward', 'motion.turnLeft', 'motion.turnRight', 'motion.stop']::text[], intro_steps = ARRAY['Plan the whole route first: lane, corner, lane…', 'Pass both transformers', 'Stop on the charging pad']::text[],
       map_definition = '{"id":"level-starter-02","name":"Power Station","schemaVersion":1,"size":{"x":6,"z":4.4},"gridSize":0.5,"floorColor":"white","start":{"x":-2.4,"z":1.3,"heading":0},"finish":{"shape":"rect","center":{"x":0.4,"z":0.9},"size":{"x":0.5,"z":0.5},"rotation":0},"entities":[{"id":"cp-1","type":"checkpoint","area":{"shape":"circle","center":{"x":-1.2,"z":0.7},"radius":0.22},"order":1},{"id":"cp-2","type":"checkpoint","area":{"shape":"circle","center":{"x":-0.4,"z":0.1},"radius":0.22},"order":2},{"id":"hedge-a1","type":"wall","from":{"x":-2.75,"z":1.72},"to":{"x":-0.78,"z":1.72},"height":0.18,"thickness":0.14},{"id":"hedge-b1","type":"wall","from":{"x":-2.75,"z":0.88},"to":{"x":-1.62,"z":0.88},"height":0.18,"thickness":0.14},{"id":"hedge-a2","type":"wall","from":{"x":-0.78,"z":1.72},"to":{"x":-0.78,"z":0.52},"height":0.18,"thickness":0.14},{"id":"hedge-b2","type":"wall","from":{"x":-1.62,"z":0.88},"to":{"x":-1.62,"z":-0.32},"height":0.18,"thickness":0.14},{"id":"hedge-a3","type":"wall","from":{"x":-0.78,"z":0.52},"to":{"x":-0.02,"z":0.52},"height":0.18,"thickness":0.14},{"id":"hedge-b3","type":"wall","from":{"x":-1.62,"z":-0.32},"to":{"x":0.82,"z":-0.32},"height":0.18,"thickness":0.14},{"id":"hedge-a4","type":"wall","from":{"x":-0.02,"z":0.52},"to":{"x":-0.02,"z":1.85},"height":0.18,"thickness":0.14},{"id":"hedge-b4","type":"wall","from":{"x":0.82,"z":-0.32},"to":{"x":0.82,"z":1.85},"height":0.18,"thickness":0.14},{"id":"dock-station","type":"wall","from":{"x":-0.019999999999999962,"z":1.85},"to":{"x":0.8200000000000001,"z":1.85},"height":0.5,"thickness":0.1}]}'::jsonb, scene_config = '{"path":[{"x":-2.75,"z":1.3},{"x":-1.2,"z":1.3},{"x":-1.2,"z":0.1},{"x":0.4,"z":0.1},{"x":0.4,"z":1.8}],"pathWidth":0.72}'::jsonb, mission_settings = '{"failOnCollision":true,"timeLimit":null,"missionTitle":"Power Station","missionDescription":"Inspect both transformers and stop on the charging pad.","stopInFinish":true,"scoring":{"completionPoints":500,"checkpointPoints":100,"timeBonus":{"parSeconds":26,"maxPoints":200},"efficiencyBonus":{"parBlocks":8,"maxPoints":200},"collisionPenalty":100},"briefing":{"story":"With spare parts delivered, the next job is power. Starter Island’s power yard went dark in the storm. The transformers must be inspected and the station needs a robot docked on its charging pad to restart.","task":"Drive the service lanes past both transformers and stop on the charging pad.","objectives":{"primary":"Inspect both transformers and stop on the charging pad without hitting anything","secondary":"Reach the pad within 26 seconds","optional":"Use 8 blocks or fewer"},"concepts":["Route planning","Waypoints","Left and right turns","Sequence"],"python":["robot.move_forward(cm)","robot.turn_left(degrees)","robot.turn_right(degrees)","robot.stop()"],"predict":"Look at the yard from above. How many corners are there, and which ones turn left and which turn right?","pseudocode":["drive to the first corner","turn left","drive past transformer A","turn right","drive past transformer B","turn right","drive onto the charging pad","stop"],"minutes":6,"tier":"easy","mechanics":[]}}'::jsonb
 WHERE slug = 'starter-02';
DELETE FROM student_objective_progress WHERE objective_id IN (SELECT id FROM level_objectives WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-02'));
DELETE FROM level_objectives WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-02');
DELETE FROM level_checkpoints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-02');
INSERT INTO level_checkpoints (level_id, code, name, sort_order, position, radius) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-02'), 'cp-1', 'Inspect transformer A', 1, '{"x":-1.2,"y":0,"z":0.7}'::jsonb, 0.22),
  ((SELECT id FROM levels WHERE slug = 'starter-02'), 'cp-2', 'Inspect transformer B', 2, '{"x":-0.4,"y":0,"z":0.1}'::jsonb, 0.22);
INSERT INTO level_objectives (level_id, code, title, objective_type, checkpoint_id, config, sort_order, required) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-02'), 'cp-1', 'Inspect transformer A', 'REACH_CHECKPOINT', (SELECT id FROM level_checkpoints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-02') AND code = 'cp-1'), '{}'::jsonb, 1, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-02'), 'cp-2', 'Inspect transformer B', 'REACH_CHECKPOINT', (SELECT id FROM level_checkpoints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-02') AND code = 'cp-2'), '{}'::jsonb, 2, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-02'), 'goal', 'Stop on the charging pad', 'REACH_GOAL', NULL, '{}'::jsonb, 3, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-02'), 'safe', 'Don’t hit any obstacles', 'AVOID_COLLISIONS', NULL, '{"maxCollisions":0}'::jsonb, 4, TRUE);
UPDATE level_hints SET title = 'Hint 1', content = 'Use the top camera to see the whole yard. Write the route down before you code it: which way is each corner — left or right?', cost = 0 WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-02') AND sort_order = 1;
INSERT INTO level_hints (level_id, title, content, cost, sort_order) SELECT (SELECT id FROM levels WHERE slug = 'starter-02'), 'Hint 1', 'Use the top camera to see the whole yard. Write the route down before you code it: which way is each corner — left or right?', 0, 1 WHERE NOT EXISTS (SELECT 1 FROM level_hints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-02') AND sort_order = 1);
UPDATE level_hints SET title = 'Hint 2', content = 'drive to the first corner → turn left → drive past transformer A → turn right → drive past transformer B → turn right → drive onto the pad → stop.', cost = 0 WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-02') AND sort_order = 2;
INSERT INTO level_hints (level_id, title, content, cost, sort_order) SELECT (SELECT id FROM levels WHERE slug = 'starter-02'), 'Hint 2', 'drive to the first corner → turn left → drive past transformer A → turn right → drive past transformer B → turn right → drive onto the pad → stop.', 0, 2 WHERE NOT EXISTS (SELECT 1 FROM level_hints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-02') AND sort_order = 2);
UPDATE level_hints SET title = 'Hint 3', content = 'move forward 120 → turn left 90 → move forward 120 → turn right 90 → move forward ? → turn right 90 → move forward ? → stop. The lanes are made of 40 cm slabs.', cost = 0 WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-02') AND sort_order = 3;
INSERT INTO level_hints (level_id, title, content, cost, sort_order) SELECT (SELECT id FROM levels WHERE slug = 'starter-02'), 'Hint 3', 'move forward 120 → turn left 90 → move forward 120 → turn right 90 → move forward ? → turn right 90 → move forward ? → stop. The lanes are made of 40 cm slabs.', 0, 3 WHERE NOT EXISTS (SELECT 1 FROM level_hints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-02') AND sort_order = 3);
UPDATE level_hints SET title = 'Hint 4', content = 'move forward 120 → turn left 90 → move forward 120 → turn right 90 → move forward 160 → turn right 90 → move forward 80 → stop.', cost = 10 WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-02') AND sort_order = 4;
INSERT INTO level_hints (level_id, title, content, cost, sort_order) SELECT (SELECT id FROM levels WHERE slug = 'starter-02'), 'Hint 4', 'move forward 120 → turn left 90 → move forward 120 → turn right 90 → move forward 160 → turn right 90 → move forward 80 → stop.', 10, 4 WHERE NOT EXISTS (SELECT 1 FROM level_hints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-02') AND sort_order = 4);

-- starter-03 · Supply Run
UPDATE levels SET title = 'Supply Run', brief_description = 'Storm debris blocks the trail to the riverside clinic. Plan a route around the crate pile and the boulder, cross the creek bridge and deliver the supplies.',
       description = 'Storm debris blocks the trail to the riverside clinic. Plan a route around the crate pile and the boulder, cross the creek bridge and deliver the supplies. Environment: Supply Trail — A storm-hit meadow trail over the creek bridge to the riverside clinic.',
       difficulty = 'EASY', environment_id = 'starter-creek-bridge', estimated_minutes = 8,
       xp_reward = 100, par_blocks = 12, par_seconds = 32,
       allowed_blocks = ARRAY['event.start', 'motion.forward', 'motion.backward', 'motion.turnLeft', 'motion.turnRight', 'motion.stop']::text[], intro_steps = ARRAY['Find a gap around the crate pile', 'Watch out for the boulder after it', 'Cross the bridge and stop on the supply pad']::text[],
       map_definition = '{"id":"level-starter-03","name":"Supply Run","schemaVersion":1,"size":{"x":6,"z":4.4},"gridSize":0.5,"floorColor":"white","start":{"x":-2.6,"z":0.8,"heading":0},"finish":{"shape":"rect","center":{"x":0.1,"z":-1.1},"size":{"x":0.5,"z":0.5},"rotation":0},"entities":[{"id":"cp-1","type":"checkpoint","area":{"shape":"circle","center":{"x":-1.3,"z":0.3},"radius":0.22},"order":1},{"id":"cp-2","type":"checkpoint","area":{"shape":"circle","center":{"x":0.1,"z":-0.35},"radius":0.22},"order":2},{"id":"crate-pile","type":"box","position":{"x":-1.3,"z":0.8},"size":{"x":0.5,"y":0.3,"z":0.5},"rotation":0,"dynamic":false},{"id":"rock-1","type":"obstacle","position":{"x":-0.35,"z":0.3},"radius":0.12,"height":0.2},{"id":"rock-2","type":"obstacle","position":{"x":-2.3,"z":1.3},"radius":0.12,"height":0.18},{"id":"fence-north","type":"wall","from":{"x":-2.95,"z":1.55},"to":{"x":0.52,"z":1.55},"height":0.12,"thickness":0.06},{"id":"fence-west","type":"wall","from":{"x":-2.95,"z":0.05},"to":{"x":-2.95,"z":1.55},"height":0.12,"thickness":0.06},{"id":"fence-east","type":"wall","from":{"x":0.52,"z":1.55},"to":{"x":0.52,"z":-2.05},"height":0.12,"thickness":0.06},{"id":"fence-south","type":"wall","from":{"x":-2.95,"z":0.05},"to":{"x":-0.31999999999999995,"z":0.05},"height":0.12,"thickness":0.06},{"id":"fence-bridge","type":"wall","from":{"x":-0.31999999999999995,"z":0.05},"to":{"x":-0.31999999999999995,"z":-2.05},"height":0.12,"thickness":0.06},{"id":"dock-clinic","type":"wall","from":{"x":-0.31999999999999995,"z":-2.05},"to":{"x":0.52,"z":-2.05},"height":0.5,"thickness":0.1}]}'::jsonb, scene_config = '{"path":[{"x":-2.9000000000000004,"z":0.8},{"x":0.1,"z":0.8},{"x":0.1,"z":-1.9999999999999998}],"pathWidth":0.84,"bridges":[{"from":{"x":0.1,"z":0.05},"to":{"x":0.1,"z":-0.75},"width":0.84,"style":"wood"}],"water":[{"points":[{"x":-3.4,"z":-0.3},{"x":-1.6,"z":-0.42},{"x":0.1,"z":-0.35},{"x":1.4,"z":-0.25},{"x":3.4,"z":-0.4}],"width":0.56,"depth":0.28}]}'::jsonb, mission_settings = '{"failOnCollision":true,"timeLimit":null,"missionTitle":"Supply Run","missionDescription":"Go around the debris, cross the bridge and stop on the clinic’s supply pad.","stopInFinish":true,"scoring":{"completionPoints":500,"checkpointPoints":100,"timeBonus":{"parSeconds":32,"maxPoints":200},"efficiencyBonus":{"parBlocks":12,"maxPoints":200},"collisionPenalty":100},"briefing":{"story":"The power is back, but the storm left the meadow trail covered in debris. The riverside clinic across the creek is waiting for its medical supplies — and your robot has no sensors yet. It will only avoid what you plan for.","task":"Plan a route around the debris, cross the creek bridge and stop on the clinic’s supply pad.","objectives":{"primary":"Deliver the supplies to the clinic pad without touching any debris","secondary":"Deliver within 32 seconds","optional":"Use 12 blocks or fewer"},"concepts":["Planned obstacle avoidance","Detours","Route planning","Sequence"],"python":["robot.move_forward(cm)","robot.turn_left(degrees)","robot.turn_right(degrees)","robot.stop()"],"predict":"Which side of the crate pile is free? After the detour, what is still in the way before the bridge?","pseudocode":["drive up to the crate pile","sidestep towards the creek","drive past the pile","sidestep back to the middle","drive to the bridge corner","turn towards the creek","cross the bridge onto the pad","stop"],"minutes":8,"tier":"medium","mechanics":["cargo"]}}'::jsonb
 WHERE slug = 'starter-03';
DELETE FROM student_objective_progress WHERE objective_id IN (SELECT id FROM level_objectives WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-03'));
DELETE FROM level_objectives WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-03');
DELETE FROM level_checkpoints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-03');
INSERT INTO level_checkpoints (level_id, code, name, sort_order, position, radius) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-03'), 'cp-1', 'Get past the crate pile', 1, '{"x":-1.3,"y":0,"z":0.3}'::jsonb, 0.22),
  ((SELECT id FROM levels WHERE slug = 'starter-03'), 'cp-2', 'Cross the creek bridge', 2, '{"x":0.1,"y":0,"z":-0.35}'::jsonb, 0.22);
INSERT INTO level_objectives (level_id, code, title, objective_type, checkpoint_id, config, sort_order, required) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-03'), 'cp-1', 'Get past the crate pile', 'REACH_CHECKPOINT', (SELECT id FROM level_checkpoints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-03') AND code = 'cp-1'), '{}'::jsonb, 1, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-03'), 'cp-2', 'Cross the creek bridge', 'REACH_CHECKPOINT', (SELECT id FROM level_checkpoints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-03') AND code = 'cp-2'), '{}'::jsonb, 2, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-03'), 'goal', 'Stop on the clinic’s supply pad', 'REACH_GOAL', NULL, '{}'::jsonb, 3, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-03'), 'safe', 'Don’t hit any obstacles', 'AVOID_COLLISIONS', NULL, '{"maxCollisions":0}'::jsonb, 4, TRUE);
UPDATE level_hints SET title = 'Hint 1', content = 'There are no sensors yet, so the robot can’t see the debris — you have to plan the path. Look from the top camera: the gap is on the creek side of the crate pile.', cost = 0 WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-03') AND sort_order = 1;
INSERT INTO level_hints (level_id, title, content, cost, sort_order) SELECT (SELECT id FROM levels WHERE slug = 'starter-03'), 'Hint 1', 'There are no sensors yet, so the robot can’t see the debris — you have to plan the path. Look from the top camera: the gap is on the creek side of the crate pile.', 0, 1 WHERE NOT EXISTS (SELECT 1 FROM level_hints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-03') AND sort_order = 1);
UPDATE level_hints SET title = 'Hint 2', content = 'drive towards the pile → turn left → sidestep → turn right → drive past the pile → turn right → back to the middle of the lane → turn left → drive to the bridge → turn left → cross and stop on the pad.', cost = 0 WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-03') AND sort_order = 2;
INSERT INTO level_hints (level_id, title, content, cost, sort_order) SELECT (SELECT id FROM levels WHERE slug = 'starter-03'), 'Hint 2', 'drive towards the pile → turn left → sidestep → turn right → drive past the pile → turn right → back to the middle of the lane → turn left → drive to the bridge → turn left → cross and stop on the pad.', 0, 2 WHERE NOT EXISTS (SELECT 1 FROM level_hints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-03') AND sort_order = 2);
UPDATE level_hints SET title = 'Hint 3', content = 'move forward 80 → turn left 90 → move forward 50 → turn right 90 → move forward 100 → turn right 90 → move forward 50 → turn left 90 → move forward ? → turn left 90 → move forward ? → stop.', cost = 0 WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-03') AND sort_order = 3;
INSERT INTO level_hints (level_id, title, content, cost, sort_order) SELECT (SELECT id FROM levels WHERE slug = 'starter-03'), 'Hint 3', 'move forward 80 → turn left 90 → move forward 50 → turn right 90 → move forward 100 → turn right 90 → move forward 50 → turn left 90 → move forward ? → turn left 90 → move forward ? → stop.', 0, 3 WHERE NOT EXISTS (SELECT 1 FROM level_hints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-03') AND sort_order = 3);
UPDATE level_hints SET title = 'Hint 4', content = 'move forward 80 → turn left 90 → move forward 50 → turn right 90 → move forward 100 → turn right 90 → move forward 50 → turn left 90 → move forward 90 → turn left 90 → move forward 190 → stop.', cost = 10 WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-03') AND sort_order = 4;
INSERT INTO level_hints (level_id, title, content, cost, sort_order) SELECT (SELECT id FROM levels WHERE slug = 'starter-03'), 'Hint 4', 'move forward 80 → turn left 90 → move forward 50 → turn right 90 → move forward 100 → turn right 90 → move forward 50 → turn left 90 → move forward 90 → turn left 90 → move forward 190 → stop.', 10, 4 WHERE NOT EXISTS (SELECT 1 FROM level_hints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-03') AND sort_order = 4);

COMMIT;